WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT id, account_id, txn_type, amount, merchant, is_flagged, new_group_flag FROM islands ORDER BY amount, id;
